121	    /**
122	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)} does,
123	     * carrying the tags in the comma separated text (see {@link Tags#normalize}; null: none). Returns the
124	     * person it belongs to.
125	     */
126	    @Transactional
127	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
128	            String corrects, String ref, String tagText) {
129	        String tagged = Tags.normalize(tagText);
130	        String reference = requireFreeRef(sheetId, ref, null);
131	        Person person = people.findByIdAndSheetId(personId, sheetId)
132	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
133	        LocalDate on = date != null ? date : sheets.claimDate(sheetId);
134	        sheets.load(sheetId, user);
135	        int terms = sheets.settings(sheetId).termsFor(person.getTerms(), person.gradeOn(on), on);
136	        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
137	        periods.requireOpen(sheetId, dueBy);
138	        requireNotRetired(person, on);
139	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
140	        Rollup.Figures before = rollup.figures(sheetId);
141	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
142	        claim.setCorrectsDate(correctsDate);
143	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy).isPresent());
144	        claim.setDueBy(dueBy);
145	        claim.setTerms(terms);
146	        claim.setRef(reference);
147	        claim.setTags(tagged);
148	        log(sheetId, user, claim, person);
149	        claims.saveAndFlush(claim);
150	        tags.use(sheetId, tagged);
151	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null,
152	                null, null, reference, tagged.isEmpty() ? null : tagged));
153	        if (claim.isLateEntry()) {
154	            events.publishEvent(new ClaimChanged("LATE_ENTRY", sheetId, user, person.getName(), amount, on, null, null));
155	        }
156	        rollup.changed(sheetId, user, before);
157	        return personId;
158	    }
