160	    /**
161	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
162	     * added again instead), and an edit is refused when a closed period contains its due-by (which an edit
163	     * leaves as it was fixed), or
164	     * when the date it is left with is after its person's retirement date, or when its external reference
165	     * (surrounding spaces removed; blank: none) is carried by another claim on the sheet, compared without
166	     * regard to case. Its tags are those in the comma separated text (see {@link Tags#normalize}; null: none).
167	     * Returns the person it belongs to.
168	     */
169	    @Transactional
170	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
171	            String corrects, String ref, String tagText) {
172	        String tagged = Tags.normalize(tagText);
173	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
174	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
175	        String reference = requireFreeRef(sheetId, ref, claimId);
176	        LocalDate on = date != null ? date : sheets.today(sheetId);
177	        periods.requireOpen(sheetId, claim.getDueBy());
178	        if (claim.getStatus() != ClaimStatus.DRAFT) {
179	            throw new ResponseStatusException(HttpStatus.CONFLICT,
180	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
181	        }
182	        requireNotLockedByOther(claim, user);
183	        people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
184	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
185	        Rollup.Figures before = rollup.figures(sheetId);
186	        claim.setAmount(amount);
187	        claim.setCorrects(corrects);
188	        claim.setCorrectsDate(correctsDate);
189	        claim.setDate(on);
190	        claim.setNote(note == null ? "" : note);
191	        claim.setRef(reference);
192	        claim.setTags(tagged);
193	        claim.setLockedBy(null);
194	        claim.setEditedBy(user);
195	        claims.flush();
196	        tags.use(sheetId, tagged);
197	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
198	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
199	                claim.getDate(), claim.getShownNumber(), null));
200	        rollup.changed(sheetId, user, before);
201	        return claim.getPersonId();
202	    }
