313	    /**
314	     * Move a claim to a status as {@link #move(String, String, long, ClaimStatus)}; a claim is voided with the
315	     * given reason, which while the sheet's list of void reasons is not empty must be on it, else the void is
316	     * refused (see {@link VoidReasons#require}).
317	     */
318	    @Transactional
319	    public long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
320	        Claim claim = claim(sheetId, claimId);
321	        if (!claim.getStatus().canBecome(next)) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT,
323	                    "A " + claim.getStatus() + " claim cannot become " + next);
324	        }
325	        Permission permission = switch (next) {
326	            case OPEN -> Permission.OPEN;
327	            case SETTLED -> Permission.SETTLE;
328	            case VOID -> Permission.VOID;
329	            default -> null;
330	        };
331	        if (permission != null && !access.allows(sheetId, user, permission)) {
332	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
333	                    "Your role may not " + permission.action() + " a claim on this sheet");
334	        }
335	        String reasonGiven = next == ClaimStatus.VOID ? voidReasons.require(sheetId, voidReason) : null;
336	        String reversed = null;
337	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
338	            requireVoidableSettled(sheetId, user, claim);
339	            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
340	        }
341	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT,
343	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
344	        }
345	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
346	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
347	                    "The user who opened a claim cannot settle it");
348	        }
349	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
350	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
351	                    "The user who last edited a claim cannot settle it");
352	        }
353	        if (next == ClaimStatus.OPEN) {
354	            requireNote(sheetId, claim);
355	        }
356	        Rollup.Figures before = rollup.figures(sheetId);
357	        if (next == ClaimStatus.OPEN) {
358	            giveNumber(sheetId, claim);
359	            claim.setOpenedBy(user);
360	        }
361	        String number = claim.getShownNumber();
362	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
363	        String due = null;
364	        if (next == ClaimStatus.SETTLED) {
365	            BigDecimal fixed = dueNow(sheetId, claim, owner);
366	            requireProof(sheetId, claim, owner, fixed);
367	            if (access.canSettle(sheetId, user, fixed)) {
368	                claim.setSettledDue(fixed);
369	                due = fixed == null ? "n/a" : fixed.toPlainString();
370	            } else {
371	                next = ClaimStatus.PENDING;
372	            }
373	        }
374	        claim.setStatus(next);
375	        if (next == ClaimStatus.VOID) {
376	            claim.setVoidReason(reasonGiven);
377	        }
378	        log(sheetId, user, claim, owner);
379	        claims.flush();
380	        String person = owner == null ? "" : owner.getName();
381	        String event = switch (next) {
382	            case OPEN -> "CLAIM_OPENED";
383	            case PENDING -> "CLAIM_PENDING";
384	            case SETTLED -> "CLAIM_SETTLED";
385	            case VOID -> "CLAIM_VOIDED";
386	            case DRAFT -> throw new IllegalStateException();
387	        };
388	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
389	                due, null, reversed, null, null, reasonGiven));
390	        if (next == ClaimStatus.SETTLED) {
391	            watches.notifyWatchers(sheetId, user, owner, number);
392	        }
393	        rollup.changed(sheetId, user, before);
394	        return claim.getPersonId();
395	    }
