397	    /**
398	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
399	     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
400	     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim due by a date inside a closed
401	     * period is refused and nothing changes. Returns the person it belongs to.
402	     */
403	    @Transactional
404	    public long defer(String sheetId, String user, long claimId, LocalDate until) {
405	        Claim claim = claim(sheetId, claimId);
406	        if (claim.getStatus() != ClaimStatus.OPEN) {
407	            throw new ResponseStatusException(HttpStatus.CONFLICT,
408	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
409	        }
410	        LocalDate today = sheets.today(sheetId);
411	        if (!until.isAfter(today)) {
412	            throw new ResponseStatusException(HttpStatus.CONFLICT,
413	                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
414	        }
415	        Rollup.Figures before = rollup.figures(sheetId);
416	        claim.setDeferredUntil(until);
417	        claims.flush();
418	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
419	        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
420	                claim.getShownNumber(), until));
421	        rollup.changed(sheetId, user, before);
422	        return claim.getPersonId();
423	    }
