425	    /**
426	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement
427	     * bound it to stays bound; so does its period (the one containing its due-by) and its number. A claim
428	     * not OPEN or PENDING, one due by a date inside a closed period, a new date after its person's
429	     * retirement date, or a re-date by
430	     * anyone but a steward is refused and nothing changes. Returns the person it belongs to.
431	     */
432	    @Transactional
433	    public long redate(String sheetId, String user, long claimId, LocalDate date) {
434	        Claim claim = claim(sheetId, claimId);
435	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
436	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-date a claim");
437	        }
438	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
439	            throw new ResponseStatusException(HttpStatus.CONFLICT,
440	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
441	        }
442	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
443	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
444	        requireNotRetired(owner, date);
445	        Rollup.Figures before = rollup.figures(sheetId);
446	        LocalDate old = claim.getDate();
447	        claim.setDate(date);
448	        claims.flush();
449	        events.publishEvent(new ClaimRedated(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
450	                claim.getShownNumber(), old, date));
451	        rollup.changed(sheetId, user, before);
452	        return claim.getPersonId();
453	    }
