455	    /**
456	     * Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps
457	     * the rest and is released from any figure a statement bound it to; a new OPEN claim of the same person
458	     * takes the amount split off, with the same date and note, the next number, opened by the user and
459	     * due by its date plus the terms then of its person's grade on its date, naming the claim it was split
460	     * from, carrying its tags, and a late entry when that claim is. It is judged by the claim split alone: a claim not OPEN, a deferred one, one due by a date inside a closed period, an amount out of range, or a
461	     * split by a role the sheet's permission matrix does not allow to open a claim is refused and nothing
462	     * changes. Returns the person it belongs to.
463	     */
464	    @Transactional
465	    public long split(String sheetId, String user, long claimId, BigDecimal amount) {
466	        Claim claim = claim(sheetId, claimId);
467	        if (claim.getStatus() != ClaimStatus.OPEN) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT,
469	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
470	        }
471	        if (Dues.deferred(claim, sheets.today(sheetId))) {
472	            throw new ResponseStatusException(HttpStatus.CONFLICT,
473	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
474	        }
475	        if (!access.allows(sheetId, user, Permission.OPEN)) {
476	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
477	        }
478	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
479	            throw new ResponseStatusException(HttpStatus.CONFLICT,
480	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
481	        }
482	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
483	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
484	        Rollup.Figures before = rollup.figures(sheetId);
485	        claim.setAmount(claim.getAmount().subtract(amount));
486	        claim.unbind();
487	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
488	        sheets.load(sheetId, user);
489	        int terms = sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate());
490	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
491	        part.setTerms(terms);
492	        part.setSplitFrom(claim.getShownNumber());
493	        part.setTags(claim.getTags());
494	        part.setLateEntry(claim.isLateEntry());
495	        giveNumber(sheetId, part);
496	        part.setOpenedBy(user);
497	        part.setStatus(ClaimStatus.OPEN);
498	        log(sheetId, user, part, owner);
499	        claims.saveAndFlush(part);
500	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
501	                claim.getShownNumber(), part.getShownNumber()));
502	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
503	                part.getDate(), part.getShownNumber(), null));
504	        rollup.changed(sheetId, user, before);
505	        return owner.getId();
506	    }
