548	     * Remind an OPEN or PENDING claim: it takes the sheet's today as its reminded date. A claim can be
549	     * reminded once per sheet's today; a claim in any other status, or one already reminded on the sheet's
550	     * today, is refused and nothing changes. A reminder changes no figure, so a claim due by a date inside a
551	     * closed period can still be reminded. Returns the person it belongs to.
552	     */
553	    @Transactional
554	    public long remind(String sheetId, String user, long claimId) {
555	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
556	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
557	        if (!claim.getStatus().unpaid()) {
558	            throw new ResponseStatusException(HttpStatus.CONFLICT,
559	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
560	        }
561	        LocalDate today = sheets.today(sheetId);
562	        if (today.equals(claim.getRemindedOn())) {
563	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today (" + today + ")");
564	        }
565	        claim.setRemindedOn(today);
566	        claims.flush();
567	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
568	        events.publishEvent(new ClaimReminded(sheetId, user, person, claim.getAmount(), claim.getDate(),
569	                claim.getShownNumber()));
570	        return claim.getPersonId();
571	    }
572	
573	    /**
574	     * Refuse opening a claim with an empty note whose due (null: n/a) is above the sheet's note threshold in
575	     * force on the claim's date.
576	     */
577	    private void requireNote(String sheetId, Claim claim) {
578	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
579	            return;
580	        }
581	        BigDecimal threshold = sheets.settings(sheetId).noteThreshold(claim.getDate());
582	        if (threshold == null) {
583	            return;
584	        }
585	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
586	        BigDecimal due = dueNow(sheetId, claim, owner);
587	        if (due != null && due.compareTo(threshold) > 0) {
588	            throw new ResponseStatusException(HttpStatus.CONFLICT,
589	                    "A claim with a due above " + threshold.toPlainString() + " needs a note to be opened");
590	        }
591	    }
592	
593	    /**
594	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the proof threshold
595	     * in force on the claim's date: its owner's grade's then when one is set, else the sheet's.
596	     */
597	    private void requireProof(String sheetId, Claim claim, Person owner, BigDecimal due) {
598	        if (due == null || claim.getProofs() > 0) {
599	            return;
600	        }
601	        String grade = owner == null ? null : owner.gradeOn(claim.getDate());
602	        BigDecimal threshold = sheets.settings(sheetId).proofThresholdFor(grade, claim.getDate());
603	        if (threshold != null && due.compareTo(threshold) > 0) {
604	            throw new ResponseStatusException(HttpStatus.CONFLICT,
605	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
606	        }
607	    }
608	
609	    /**
610	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
611	     * Only a steward approves, never the user who opened the claim or last edited it; a claim not PENDING or due by a date inside a
612	     * closed period is refused and nothing changes. Returns the person it belongs to.
613	     */
614	    @Transactional
615	    public long approve(String sheetId, String user, long claimId) {
616	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
617	        if (user.equals(claim.getOpenedBy())) {
618	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
619	        }
620	        if (user.equals(claim.getEditedBy())) {
621	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
622	                    "The user who last edited a claim cannot approve it");
623	        }
624	        Rollup.Figures before = rollup.figures(sheetId);
625	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
626	        BigDecimal fixed = dueNow(sheetId, claim, owner);
627	        requireProof(sheetId, claim, owner, fixed);
628	        claim.setSettledDue(fixed);
629	        claim.setStatus(ClaimStatus.SETTLED);
630	        log(sheetId, user, claim, owner);
631	        claims.flush();
632	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
633	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
634	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
635	        rollup.changed(sheetId, user, before);
636	        return claim.getPersonId();
637	    }
638	
639	    /**
640	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
641	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
642	     * steward re-settles; a claim not SETTLED or due by a date inside a closed period is refused and nothing changes.
643	     * Returns the person it belongs to.
644	     */
645	    @Transactional
646	    public long resettle(String sheetId, String user, long claimId) {
647	        Claim claim = claim(sheetId, claimId);
648	        if (claim.getStatus() != ClaimStatus.SETTLED) {
649	            throw new ResponseStatusException(HttpStatus.CONFLICT,
650	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
651	        }
652	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
653	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
654	        }
655	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
656	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
657	        Rollup.Figures before = rollup.figures(sheetId);
658	        BigDecimal old = claim.getSettledDue();
659	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
660	        claim.setSettledDue(fixed);
661	        claim.logStatus(user, sheets.today(sheetId), fixed);
662	        claims.flush();
663	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
664	                claim.getShownNumber(), old, fixed));
665	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
666	        rollup.changed(sheetId, user, before);
667	        return claim.getPersonId();
668	    }
669	
670	    /**
671	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
672	     * that statement counted it). Only a steward rejects; a claim not PENDING or due by a date inside a closed
673	     * period is refused and nothing changes. Returns the person it belongs to.
674	     */
675	    @Transactional
676	    public long reject(String sheetId, String user, long claimId, String reason) {
677	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
678	        Rollup.Figures before = rollup.figures(sheetId);
679	        claim.setStatus(ClaimStatus.OPEN);
680	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
681	        log(sheetId, user, claim, owner);
682	        claims.flush();
683	        String person = owner == null ? "" : owner.getName();
684	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
685	                claim.getDate(), claim.getShownNumber(), null, reason));
686	        rollup.changed(sheetId, user, before);
687	        return claim.getPersonId();
688	    }
689	
690	    /**
691	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
692	     * date and takes the next number in the sequence it would be numbered in now (the sheet's, or its
693	     * period's while period numbering is on), its old number never given again; a draft gets none. It is
694	     * released from any figure a statement bound it to (live again until its new person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
695	     * correction, a claim due by a date inside a closed period or after the new person's retirement date, or a move
696	     * by a role the sheet's permission matrix does not allow (a steward, unless set) is refused and nothing changes. Returns the people it moved from and to.
697	     */
698	    @Transactional
699	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
700	        return reassign(sheetId, user, claimId, toPersonId, false);
701	    }
702	
703	    /**
704	     * As {@link #reassign(String, String, long, long)}; when {@code sameAllowed}, a claim already the new
705	     * person's is moved to them again (listed as their newest claim) rather than refused, as a bulk move does.
706	     */
707	    @Transactional
708	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId, boolean sameAllowed) {
709	        Claim claim = claim(sheetId, claimId);
710	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
711	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
712	        }
713	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
714	                && claim.getStatus() != ClaimStatus.PENDING) {
715	            throw new ResponseStatusException(HttpStatus.CONFLICT,
716	                    "A " + claim.getStatus() + " claim cannot be reassigned");
717	        }
718	        if (claim.isCorrection()) {
719	            throw new ResponseStatusException(HttpStatus.CONFLICT,
720	                    "A correction belongs with the claim it corrects and cannot be reassigned");
721	        }
722	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
723	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
724	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
725	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
726	        if (!sameAllowed && from.getId().equals(to.getId())) {
727	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
728	        }
729	        requireNotRetired(to, claim.getDate());
730	        Rollup.Figures before = rollup.figures(sheetId);
731	        claim.setPersonId(to.getId());
732	        claim.unbind();
733	        renumber(sheetId, claim);
734	        claims.flush();
735	        claims.relist(claim.getId());
736	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
737	                claim.getShownNumber(), from.getName(), to.getName()));
738	        rollup.changed(sheetId, user, before);
739	        return new long[] { from.getId(), to.getId() };
740	    }
741	
742	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
743	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
744	        Claim claim = claim(sheetId, claimId);
745	        if (claim.getStatus() != ClaimStatus.PENDING) {
746	            throw new ResponseStatusException(HttpStatus.CONFLICT,
747	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
748	        }
749	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
750	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
751	        }
752	        return claim;
753	    }
754	
755	    /**
756	     * A SETTLED claim may be voided only by a steward, and only while the sheet's today is no more than
757	     * 7 days after the date its status log records it SETTLED.
758	     */
759	    private void requireVoidableSettled(String sheetId, String user, Claim claim) {
760	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
761	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
762	        }
763	        LocalDate settledOn = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
764	                .map(ClaimLogLine::getOn).reduce((a, b) -> b).orElse(null);
765	        LocalDate today = sheets.today(sheetId);
766	        if (settledOn == null || today.isAfter(settledOn.plusDays(7))) {
767	            throw new ResponseStatusException(HttpStatus.CONFLICT,
768	                    "A SETTLED claim can only be voided within 7 days of its settlement"
769	                            + (settledOn == null ? "" : " (" + settledOn + ")"));
770	        }
771	    }
772	
773	    private Claim claim(String sheetId, long claimId) {
774	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
775	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
776	        periods.requireOpen(sheetId, claim.getDueBy());
777	        return claim;
778	    }
779	
780	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
781	    private void log(String sheetId, String user, Claim claim, Person owner) {
782	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
783	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
784	        claim.logStatus(user, sheets.today(sheetId), due);
785	    }
786	
787	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
788	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
789	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
790	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
791	    }
792	
793	    /** Give a claim arriving on the sheet from another, unnumbered there, the sheet's next number as opening does. */
794	    public void numberArrived(String sheetId, Claim claim) {
795	        giveNumber(sheetId, claim);
796	        claims.flush();
797	    }
798	
799	    /**
800	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
801	     * sheet's today is on or after it, the next in the period its due-by falls in (<period name>-<n>), or
802	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
803	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
804	     */
805	    private void giveNumber(String sheetId, Claim claim) {
806	        if (!numberingOn(sheetId)) {
807	            claim.setNumber(sheets.nextClaimNumber(sheetId));
808	            return;
809	        }
810	        sheetRows.lockById(sheetId);
811	        Period period = periodOf(sheetId, claim.getDueBy());
812	        String sequence = sequenceOf(sheetId, claim.getDueBy());
813	        int n = claims.lastInSequence(sheetId, sequence) + 1;
814	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
815	    }
816	
817	    /**
818	     * Give a numbered claim the next number in the sequence it would be numbered in now; the place it
819	     * leaves in a period sequence is kept as taken, so it is never given again. A draft stays unnumbered.
820	     */
821	    private void renumber(String sheetId, Claim claim) {
822	        if (claim.getShownNumber() == null) {
823	            return;
824	        }
825	        if (claim.getPeriodSequence() != null) {
826	            claims.retireNumber(sheetId, claim.getPeriodSequence(), claim.getPeriodSeqNumber());
827	        }
828	        claim.clearNumber();
829	        giveNumber(sheetId, claim);
830	    }
831	
832	    /** Whether the sheet's period numbering from is set and the sheet's today is on or after it. */
833	    private boolean numberingOn(String sheetId) {
834	        LocalDate from = sheets.periodNumberingFrom(sheetId);
835	        return from != null && !sheets.today(sheetId).isBefore(from);
836	    }
837	
838	    /** The period whose dates contain the date, or null when none does. */
839	    private Period periodOf(String sheetId, LocalDate date) {
840	        return periods.list(sheetId).stream().filter(p -> p.contains(date)).findFirst().orElse(null);
841	    }
842	
843	    /** The period sequence a claim due by the date counts in ('P<period id>', or 'X' for no period). */
844	    private String sequenceOf(String sheetId, LocalDate date) {
845	        Period period = periodOf(sheetId, date);
846	        return period == null ? "X" : "P" + period.getId();
847	    }
848	
849	    /**
850	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
851	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
852	     * correction corrects (its rounding goes by it); null for any other claim.
853	     */
854	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
855	        if (amount.signum() >= 0) {
856	            if (corrects != null) {
857	                throw new ResponseStatusException(HttpStatus.CONFLICT,
858	                        "Only a correction (a negative amount) names a claim it corrects");
859	            }
860	            return null;
861	        }
862	        if (corrects == null) {
863	            throw new ResponseStatusException(HttpStatus.CONFLICT,
864	                    "A negative amount is a correction; name the number of the settled claim it corrects");
865	        }
866	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
867	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
868	                .map(Claim::getDate).findFirst()
869	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
870	                        "Claim " + corrects + " is not a settled claim of this person"));
871	    }
872	
873	    /** Refuse a claim dated after its person's retirement date. */
874	    private static void requireNotRetired(Person person, LocalDate date) {
875	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
876	            throw new ResponseStatusException(HttpStatus.CONFLICT,
877	                    person.getName() + " is retired from " + person.getRetiredFrom()
878	                            + "; a claim cannot be dated after that");
879	        }
880	    }
881	}
